'use strict';

/**
 * 汽水音乐官方 PC 客户端签名桥接 / SodaMusic official desktop signature bridge
 *
 * 背景 / Context
 *   /luna/pc/track_v2 会校验字节系签名头（X-Helios / X-Medusa）。签名由官方客户端内置的
 *   原生安全模块生成，纯 JS 无法复刻；没有有效签名时服务端返回 HTTP 200 + 空 body。
 *   The upstream endpoint validates ByteDance signature headers generated by the official
 *   client's native module, which cannot be reimplemented in JavaScript.
 *
 * 本模块的定位 / Scope
 *   只在本机检测到官方客户端、且**用户显式授权**之后，复用它的 bdms 原生模块给请求签名，
 *   作为播放回退链的第一环。读不到客户端、未授权、模块加载失败、签名报错等任何情况都必须
 *   静默降级，由调用方继续走未签名请求与 SEO 回退接口。
 *   This module is strictly best-effort and must never throw into playback.
 *
 * 签名来源 / Where signatures come from
 *   签名值不落盘、不硬编码：每次请求都由原生模块按「当前 URL + 当前请求头 + 本机设备身份」
 *   现算，代码里没有任何固定的 X-Helios / X-Medusa 常量，也不含密钥。
 *   Signatures are generated per request by the native module; none of them is a constant.
 *
 * 授权方式 / How authorization works
 *   与「打开客户端获取授权」一致：用户点击授权后，Mineradio 打开官方客户端让用户在其中登录，
 *   然后只在本地记录「设备身份 + 原生模块位置」作为授权凭据。本模块不读取、不复制、不上传
 *   任何账号凭据；deviceId 只是签名与登录态绑定所需的设备标识。
 *   Authorization is an explicit user action that opens the official client; only a local
 *   device-identity record is stored. No credential is read, copied, or transmitted.
 *
 * 分发约束 / Distribution constraint（重要）
 *   bdms.node / metasecml.dll 属于字节专有二进制，禁止提交进本仓库、禁止随安装包分发、
 *   禁止作为附件公开。本模块只把「用户自己机器上已安装的客户端」里的文件复制到用户主目录下的
 *   缓存目录内使用，仓库与安装包中不包含任何官方二进制。
 *   The proprietary binaries are never bundled nor committed: they are only copied locally
 *   from the user's own installation into a per-user cache directory.
 */

const childProcess = require('child_process');
const crypto = require('crypto');
const fs = require('fs');
const os = require('os');
const path = require('path');

const BRIDGE_ENABLED = process.env.QISHUI_CLIENT_BRIDGE !== '0';
const CLIENT_DIR_ENV_KEY = 'QISHUI_CLIENT_DIR';
const CACHE_ROOT = process.env.QISHUI_NATIVE_CACHE_DIR
  || path.join(os.homedir(), '.mineradio', 'qishui-native');
const NATIVE_MODULE_NAME = 'bdms.node';
const DEVICE_ID_FILE = 'device-id.txt';
const AUTHORIZATION_FILE = 'authorization.json';
// 官方客户端安装目录的常见命名，用于在 Programs 等目录下做一次浅扫描。
const CLIENT_DIR_NAME_RE = /汽水|soda\s?music|qishui|qishuimusic/i;
// 依赖库扩展名：只复制原生二进制，避免把客户端整棵目录树搬过来。
const NATIVE_LIBRARY_RE = /\.(dll|dylib|so|node)$/i;
const MAX_NATIVE_FILES = 24;
const MAX_NATIVE_BYTES = 64 * 1024 * 1024;
const MAX_SCAN_ENTRIES = 4000;
const MAX_SCAN_DEPTH = 8;

let cachedStatus = null;
let cachedBinding = null;
let cachedSigner = null;
let cachedDeviceId = '';
let signerFailed = false;

function normalizeText(value) {
  return String(value == null ? '' : value).trim();
}

function existingDirectory(candidate) {
  const value = normalizeText(candidate);
  if (!value) return '';
  try {
    return fs.statSync(value).isDirectory() ? path.resolve(value) : '';
  } catch (_) {
    return '';
  }
}

function listDirectorySafe(dir) {
  try {
    return fs.readdirSync(dir, { withFileTypes: true });
  } catch (_) {
    return [];
  }
}

/**
 * 官方客户端的候选安装位置 / Candidate installation roots
 */
function candidateClientRoots() {
  const roots = [];
  const seen = new Set();
  const push = value => {
    const resolved = existingDirectory(value);
    if (!resolved || seen.has(resolved)) return;
    seen.add(resolved);
    roots.push(resolved);
  };

  push(process.env[CLIENT_DIR_ENV_KEY]);

  const home = os.homedir();
  if (process.platform === 'win32') {
    const bases = [
      process.env.LOCALAPPDATA && path.join(process.env.LOCALAPPDATA, 'Programs'),
      process.env.LOCALAPPDATA,
      process.env.APPDATA,
      process.env.ProgramFiles || process.env.PROGRAMFILES,
      process.env['ProgramFiles(x86)'],
    ].filter(Boolean);
    const names = ['汽水音乐', 'SodaMusic', 'Soda Music', 'qishui'];
    for (const base of bases) {
      for (const name of names) push(path.join(base, name));
    }
    // 官网安装器偶尔使用带版本或公司前缀的目录名，浅扫一层常见安装根目录兜底。
    const scanRoots = [
      process.env.LOCALAPPDATA && path.join(process.env.LOCALAPPDATA, 'Programs'),
      process.env.LOCALAPPDATA,
      process.env.APPDATA,
    ].filter(Boolean);
    for (const scanRoot of scanRoots) {
      for (const entry of listDirectorySafe(scanRoot)) {
        if (entry.isDirectory() && CLIENT_DIR_NAME_RE.test(entry.name)) {
          push(path.join(scanRoot, entry.name));
        }
      }
    }
  } else if (process.platform === 'darwin') {
    const names = ['汽水音乐', 'SodaMusic', 'Soda Music'];
    for (const name of names) {
      push(path.join('/Applications', name + '.app'));
      push(path.join(home, 'Applications', name + '.app'));
    }
    for (const entry of listDirectorySafe('/Applications')) {
      if (entry.isDirectory() && CLIENT_DIR_NAME_RE.test(entry.name)) {
        push(path.join('/Applications', entry.name));
      }
    }
  } else {
    const names = ['汽水音乐', 'SodaMusic', 'soda-music'];
    for (const name of names) {
      push(path.join(home, '.local/share', name));
      push(path.join('/opt', name));
      push(path.join(home, 'Applications', name));
    }
  }

  // Wine：官方客户端在 Linux/macOS 下的常见安装痕迹（issue #452 提到可走 wine）。
  if (process.platform !== 'win32') {
    const wineUsers = path.join(home, '.wine/drive_c/users');
    for (const entry of listDirectorySafe(wineUsers)) {
      if (!entry.isDirectory()) continue;
      const programs = path.join(wineUsers, entry.name, 'AppData/Local/Programs');
      for (const nested of listDirectorySafe(programs)) {
        if (nested.isDirectory() && CLIENT_DIR_NAME_RE.test(nested.name)) {
          push(path.join(programs, nested.name));
        }
      }
    }
  }

  return roots;
}

/**
 * 在候选目录里定位 bdms.node / Locate the native signature module
 * 采用有界广度优先遍历，避免在异常目录结构上失控。
 */
function findNativeModuleDir(root) {
  const queue = [{ dir: root, depth: 0 }];
  let visited = 0;
  while (queue.length && visited < MAX_SCAN_ENTRIES) {
    const current = queue.shift();
    visited += 1;
    if (current.depth > MAX_SCAN_DEPTH) continue;
    const entries = listDirectorySafe(current.dir);
    for (const entry of entries) {
      if (visited >= MAX_SCAN_ENTRIES) break;
      if (entry.isFile()) {
        if (entry.name.toLowerCase() === NATIVE_MODULE_NAME) return current.dir;
      } else if (entry.isDirectory()) {
        queue.push({ dir: path.join(current.dir, entry.name), depth: current.depth + 1 });
      }
    }
  }
  return '';
}

function nativeFilesIn(dir) {
  const files = [];
  let bytes = 0;
  for (const entry of listDirectorySafe(dir)) {
    if (!entry.isFile() || !NATIVE_LIBRARY_RE.test(entry.name)) continue;
    const full = path.join(dir, entry.name);
    let size = 0;
    try {
      size = fs.statSync(full).size;
    } catch (_) {
      continue;
    }
    if (files.length >= MAX_NATIVE_FILES || bytes + size > MAX_NATIVE_BYTES) break;
    bytes += size;
    files.push({ name: entry.name, full, size });
  }
  return files;
}

function cacheDirFor(sourceDir) {
  const hash = crypto.createHash('sha1').update(sourceDir).digest('hex').slice(0, 12);
  return path.join(CACHE_ROOT, hash);
}

/**
 * 把官方二进制复制到用户缓存目录 / Stage the proprietary binaries locally
 * 复制而不是原地 require：安装目录可能只读，且原生依赖库需要在同一目录才能被解析。
 */
function stageNativeFiles(sourceDir, files) {
  const target = cacheDirFor(sourceDir);
  fs.mkdirSync(target, { recursive: true, mode: 0o700 });
  for (const file of files) {
    const destination = path.join(target, file.name);
    let currentSize = -1;
    try {
      currentSize = fs.statSync(destination).size;
    } catch (_) {}
    if (currentSize === file.size) continue;
    fs.copyFileSync(file.full, destination);
    try {
      fs.chmodSync(destination, 0o600);
    } catch (_) {}
  }
  return target;
}

function isUsableDeviceId(value) {
  return /^\d{6,24}$/.test(normalizeText(value));
}

/**
 * 设备身份 / Device identity
 * 签名结果与登录态绑定，因此优先采用「扫码登录时使用的设备身份」，让签名用的 deviceId
 * 与请求 query 里的 device_id 完全一致；拿不到时才在本地生成并持久化一个。
 */
function readOrCreateDeviceId(preferred) {
  const candidate = normalizeText(preferred);
  if (isUsableDeviceId(candidate)) {
    cachedDeviceId = candidate;
    const file = path.join(CACHE_ROOT, DEVICE_ID_FILE);
    try {
      if (normalizeText(fs.readFileSync(file, 'utf8')) !== candidate) {
        fs.mkdirSync(CACHE_ROOT, { recursive: true, mode: 0o700 });
        fs.writeFileSync(file, candidate, { mode: 0o600 });
      }
    } catch (_) {}
    return candidate;
  }
  if (isUsableDeviceId(cachedDeviceId)) return cachedDeviceId;
  const file = path.join(CACHE_ROOT, DEVICE_ID_FILE);
  try {
    const stored = normalizeText(fs.readFileSync(file, 'utf8'));
    if (isUsableDeviceId(stored)) {
      cachedDeviceId = stored;
      return stored;
    }
  } catch (_) {}
  let value = String(crypto.randomInt(1, 10));
  while (value.length < 16) value += String(crypto.randomInt(0, 10));
  cachedDeviceId = value;
  try {
    fs.mkdirSync(CACHE_ROOT, { recursive: true, mode: 0o700 });
    fs.writeFileSync(file, value, { mode: 0o600 });
  } catch (_) {}
  return value;
}

/**
 * 取签名将使用的设备身份 / The device id the signer will use
 * 不加载原生模块，便于在没有官方客户端时也保持一致的身份。
 */
function getQishuiClientDeviceId(preferred) {
  return readOrCreateDeviceId(preferred);
}

// ---------------------------------------------------------------------------
// 本地授权记录 / Local authorization record
//
// 签名能力只有在用户显式授权后才可用。授权记录只保存「设备身份 + 已复制的原生模块位置 +
// 时间」，不含任何账号凭据或签名值。
// ---------------------------------------------------------------------------

function authorizationFile() {
  return path.join(CACHE_ROOT, AUTHORIZATION_FILE);
}

function readAuthorization() {
  try {
    const parsed = JSON.parse(fs.readFileSync(authorizationFile(), 'utf8'));
    if (!parsed || typeof parsed !== 'object') return null;
    return parsed;
  } catch (_) {
    return null;
  }
}

function writeAuthorization(record) {
  try {
    fs.mkdirSync(CACHE_ROOT, { recursive: true, mode: 0o700 });
    fs.writeFileSync(authorizationFile(), JSON.stringify(record, null, 2), { mode: 0o600 });
    return true;
  } catch (_) {
    return false;
  }
}

/**
 * 当前生效的授权 / The authorization currently in effect
 * 原生模块被移动或删除后授权自动失效，避免拿着过期凭据去签名。
 */
function currentAuthorization() {
  if (!BRIDGE_ENABLED) return null;
  const record = readAuthorization();
  if (!record || !Number(record.at) || !isUsableDeviceId(record.deviceId) || !normalizeText(record.nativeDir)) return null;
  try {
    if (!fs.statSync(path.join(record.nativeDir, NATIVE_MODULE_NAME)).isFile()) return null;
  } catch (_) {
    return null;
  }
  return record;
}

/**
 * 定位官方客户端主程序 / Locate the official client executable
 */
function findClientExecutable(clientDir) {
  const root = existingDirectory(clientDir);
  if (!root) return '';
  if (/\.app$/i.test(root)) {
    const macosDir = path.join(root, 'Contents', 'MacOS');
    for (const entry of listDirectorySafe(macosDir)) {
      if (!entry.isFile()) continue;
      const full = path.join(macosDir, entry.name);
      try {
        if (fs.statSync(full).mode & 0o111) return full;
      } catch (_) {}
    }
    return '';
  }
  const executables = listDirectorySafe(root)
    .filter(entry => entry.isFile() && /\.exe$/i.test(entry.name) && !/unins|uninstall|setup|crashpad|elevate/i.test(entry.name))
    .map(entry => path.join(root, entry.name));
  if (!executables.length) return '';
  return executables.find(item => CLIENT_DIR_NAME_RE.test(path.basename(item))) || executables[0];
}

/**
 * 打开官方客户端 / Launch the official client
 * detached + unref：客户端是用户自己的独立程序，不能随 Mineradio 一起退出。
 */
function launchClient(executable) {
  return new Promise(resolve => {
    let child;
    try {
      child = childProcess.spawn(executable, [], { detached: true, stdio: 'ignore', windowsHide: false });
    } catch (err) {
      resolve({ ok: false, reason: 'launch_failed', error: normalizeText(err && err.message || err).slice(0, 200) });
      return;
    }
    child.once('error', err => {
      resolve({ ok: false, reason: 'launch_failed', error: normalizeText(err && err.message || err).slice(0, 200) });
    });
    // 报告 spawn 成功即可：是否真正打开由用户判断，避免把平台的时序细节暴露成授权失败。
    setTimeout(() => resolve({ ok: true, reason: '' }), 400);
    if (typeof child.unref === 'function') child.unref();
  });
}

/**
 * 不同构建的导出形状不一致，逐个探测可用的签名实现。
 * The binding export shape varies between client builds, so probe defensively.
 */
function normalizeBinding(loaded) {
  const candidates = [
    loaded,
    loaded && loaded.default,
    loaded && loaded.bdms,
    loaded && loaded.default && loaded.default.bdms,
  ];
  for (const candidate of candidates) {
    if (candidate && typeof candidate.generateHttpSignatureHeaders === 'function') return candidate;
  }
  if (typeof loaded === 'function') {
    try {
      const built = loaded();
      if (built && typeof built.generateHttpSignatureHeaders === 'function') return built;
    } catch (_) {}
  }
  return null;
}

function loadBinding(nativeDir) {
  const modulePath = path.join(nativeDir, NATIVE_MODULE_NAME);
  // 把 bdms.node 与依赖库放在同一个缓存目录即可解析依赖：Node 通过
  // LoadLibraryExW(LOAD_WITH_ALTERED_SEARCH_PATH) 加载 .node 时，会优先在模块自身
  // 所在目录查找依赖库，因此不需要改动 PATH，也就不会污染子进程环境。
  const loaded = require(modulePath);
  return normalizeBinding(loaded);
}

function buildHeaderLinePayload(headers) {
  // SDK 期望 "key\r\nvalue" 逐行拼接，行与行之间用 \n 分隔。
  return Object.keys(headers || {})
    .filter(name => headers[name] != null && String(headers[name]) !== '')
    .map(name => name + '\r\n' + String(headers[name]))
    .join('\n');
}

/**
 * 解析 SDK 返回的签名头 / Parse the returned signature payload
 * 兼容两种常见形状：`Name: value` 单行，以及 `Name\r\nValue` 交替行。
 */
function parseHeaderLinePayload(text) {
  const out = {};
  const lines = String(text == null ? '' : text).split('\n').map(line => line.replace(/\r/g, ''));
  let pendingName = '';
  for (const line of lines) {
    if (!line) continue;
    const separator = line.indexOf(':');
    if (separator > 0 && /^[A-Za-z0-9-]{2,64}$/.test(line.slice(0, separator))) {
      out[line.slice(0, separator)] = line.slice(separator + 1).trim();
      pendingName = '';
      continue;
    }
    if (pendingName) {
      out[pendingName] = line;
      pendingName = '';
      continue;
    }
    if (/^[A-Za-z0-9-]{2,64}$/.test(line)) pendingName = line;
  }
  return out;
}

function resolveNative() {
  if (cachedStatus && cachedStatus.ready) return cachedStatus;
  if (cachedStatus && cachedStatus.attempted && !cachedStatus.available) return cachedStatus;
  const status = {
    supported: process.platform === 'win32' || process.platform === 'darwin' || process.platform === 'linux',
    enabled: BRIDGE_ENABLED,
    attempted: true,
    available: false,
    ready: false,
    installed: false,
    clientDir: '',
    executable: '',
    nativeDir: '',
    reason: '',
    error: '',
  };
  if (!BRIDGE_ENABLED) {
    status.reason = 'disabled';
    cachedStatus = status;
    return status;
  }
  let root = '';
  let nativeSource = '';
  for (const candidate of candidateClientRoots()) {
    const found = findNativeModuleDir(candidate);
    if (found) {
      root = candidate;
      nativeSource = found;
      break;
    }
  }
  if (!nativeSource) {
    status.reason = 'client_not_found';
    cachedStatus = status;
    return status;
  }
  status.installed = true;
  status.clientDir = root;
  status.executable = findClientExecutable(root);
  try {
    const files = nativeFilesIn(nativeSource);
    if (!files.some(file => file.name.toLowerCase() === NATIVE_MODULE_NAME)) {
      status.reason = 'native_module_missing';
      cachedStatus = status;
      return status;
    }
    const stagedDir = stageNativeFiles(nativeSource, files);
    status.nativeDir = stagedDir;
    const binding = loadBinding(stagedDir);
    if (!binding) {
      status.reason = 'binding_unsupported';
      cachedStatus = status;
      return status;
    }
    status.available = true;
    status.ready = true;
    cachedBinding = binding;
  } catch (err) {
    // 复制/加载失败只记录原因，调用方继续走未签名与 SEO 回退。
    status.reason = 'native_load_failed';
    status.error = normalizeText(err && err.message || err).slice(0, 300);
  }
  cachedStatus = status;
  return status;
}

function ensureSigner() {
  if (cachedSigner || signerFailed) return cachedSigner;
  // 未经用户授权不得签名：授权的语义就是「打开官方客户端并绑定设备身份」。
  const authorization = currentAuthorization();
  if (!authorization) return null;
  const status = resolveNative();
  if (!status.ready || !cachedBinding) return null;
  const deviceId = readOrCreateDeviceId(authorization.deviceId);
  try {
    // 官方源码要求 init 接收对象而不是字符串。
    cachedBinding.init({ deviceId });
  } catch (err) {
    signerFailed = true;
    status.available = false;
    status.ready = false;
    status.reason = 'native_init_failed';
    status.error = normalizeText(err && err.message || err).slice(0, 300);
    return null;
  }
  cachedSigner = { binding: cachedBinding, deviceId };
  return cachedSigner;
}

/**
 * 探测官方客户端与签名模块的就绪状态 / Probe the bridge state
 * 不会抛异常，也不会触发网络请求。
 */
function getQishuiClientBridgeStatus() {
  const status = resolveNative();
  const authorization = currentAuthorization();
  return {
    enabled: status.enabled,
    supported: status.supported,
    installed: status.installed,
    // ready 表示原生模块已可用；signing 表示「已加载且用户已授权」，可以直接签名。
    ready: status.ready,
    authorized: !!authorization,
    signing: !!(status.ready && authorization),
    reason: status.reason,
    error: status.error,
    authorizedAt: authorization ? Number(authorization.at) : 0,
    authorizedDeviceId: authorization ? authorization.deviceId : '',
    // 本地绝对路径只用于本机诊断，不写入仓库与更新日志。
    clientDir: status.clientDir,
    executable: status.executable,
    nativeDir: status.nativeDir,
  };
}

/**
 * 用户显式授权 / Explicit user authorization
 *
 * 与「打开客户端获取授权」对应：先打开官方客户端让用户在其中登录，再在本地记录设备身份。
 * 只做本机记录与一个「能否成功产生签名」的自检，不读取任何账号凭据，也不做网络请求。
 */
async function authorizeQishuiClientBridge(options) {
  const opts = options && typeof options === 'object' ? options : {};
  const status = getQishuiClientBridgeStatus();
  if (!status.enabled) return { ok: false, reason: 'disabled', launched: false };
  if (!status.installed) return { ok: false, reason: 'client_not_found', launched: false };
  if (!status.ready) return { ok: false, reason: status.reason || 'native_unavailable', launched: false, error: status.error || '' };
  let launched = false;
  let launchError = '';
  if (status.executable && opts.launch !== false) {
    const launchedResult = await launchClient(status.executable);
    launched = !!launchedResult.ok;
    launchError = launchedResult.error || '';
  }
  const deviceId = readOrCreateDeviceId(opts.deviceId);
  const record = {
    at: Date.now(),
    deviceId,
    clientDir: status.clientDir,
    nativeDir: status.nativeDir,
    // 客户端是否被成功拉起只作为诊断信息，不作为授权成功与否的判据。
    launched,
  };
  if (!writeAuthorization(record)) {
    return { ok: false, reason: 'authorization_not_persisted', launched, error: '' };
  }
  cachedSigner = null;
  signerFailed = false;
  // 自检：真正让原生模块产一次签名，确认这次授权可以直接用于后续请求。
  const probe = signQishuiClientRequest('https://api.qishui.com/luna/pc/track_v2?aid=386088&app_name=luna_pc', {
    'Accept': 'application/json,text/plain,*/*',
  });
  if (!probe.ok) {
    return {
      ok: false,
      reason: probe.reason || 'signature_self_test_failed',
      launched,
      error: probe.error || launchError || '',
      deviceId,
    };
  }
  return { ok: true, reason: '', launched, error: launchError, deviceId };
}

/**
 * 撤销授权 / Revoke authorization
 * 只删本地记录，不动官方客户端的任何文件。
 */
function revokeQishuiClientAuthorization() {
  cachedSigner = null;
  signerFailed = false;
  try {
    fs.rmSync(authorizationFile(), { force: true });
  } catch (_) {
    return false;
  }
  return true;
}

/**
 * 为一次请求生成签名头 / Sign a single request
 * 未授权时不返回任何签名，调用方自然降级到未签名请求与 SEO 回退。
 * @param {string} targetUrl 完整请求 URL（签名覆盖 query，必须与实际发送的一致）
 * @param {object} headers   将被发送的请求头
 * @returns {{ok: boolean, headers: object, reason: string, deviceId: string}}
 */
function signQishuiClientRequest(targetUrl, headers) {
  const url = normalizeText(targetUrl);
  if (!url) return { ok: false, headers: {}, reason: 'missing_url', deviceId: '' };
  if (!BRIDGE_ENABLED) return { ok: false, headers: {}, reason: 'disabled', deviceId: '' };
  // 参数只用于提前给出更准确的降级原因，凭据一律以本地授权记录为准。
  const signer = ensureSigner();
  if (!signer) {
    if (!currentAuthorization()) return { ok: false, headers: {}, reason: 'client_not_authorized', deviceId: '' };
    const status = cachedStatus || getQishuiClientBridgeStatus();
    return { ok: false, headers: {}, reason: status.reason || 'signer_unavailable', deviceId: '' };
  }
  try {
    const raw = signer.binding.generateHttpSignatureHeaders(url, buildHeaderLinePayload(headers || {}));
    const parsed = parseHeaderLinePayload(raw);
    const names = Object.keys(parsed);
    if (!names.length) {
      return { ok: false, headers: {}, reason: 'empty_signature', deviceId: signer.deviceId };
    }
    return { ok: true, headers: parsed, reason: '', deviceId: signer.deviceId };
  } catch (err) {
    return {
      ok: false,
      headers: {},
      reason: 'sign_failed',
      deviceId: signer.deviceId,
      error: normalizeText(err && err.message || err).slice(0, 300),
    };
  }
}

/**
 * 清空缓存，供诊断与测试使用 / Reset memoized state
 */
function resetQishuiClientBridge() {
  cachedStatus = null;
  cachedBinding = null;
  cachedSigner = null;
  cachedDeviceId = '';
  signerFailed = false;
}

module.exports = {
  getQishuiClientBridgeStatus,
  getQishuiClientDeviceId,
  authorizeQishuiClientBridge,
  revokeQishuiClientAuthorization,
  signQishuiClientRequest,
  resetQishuiClientBridge,
  _test: {
    buildHeaderLinePayload,
    parseHeaderLinePayload,
    normalizeBinding,
    findNativeModuleDir,
    findClientExecutable,
    candidateClientRoots,
    isUsableDeviceId,
    readAuthorization,
    writeAuthorization,
  },
};
